    for subject, category_id, stem in (
        XPost.objects.filter(status='posted').values_list('subject', 'category_id', 'stem')
    ):
        Question.objects.filter(
            subject=subject, category_id=category_id, stem=stem, template__isnull=True,
        ).update(x_round=1)


